@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="mb-3 d-flex gap-2 align-items-end">
    <div>
        <label class="form-label">Filter by Status</label>
        <select class="form-select" @bind="statusFilter">
            <option value="">All</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div>
        <label class="form-label">Search Destination</label>
        <input class="form-control" @bind="destinationFilter" @bind:event="oninput" placeholder="Search..." />
    </div>
    <button class="btn btn-primary" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                </div>
            </div>
            <div class="mt-2">
                <button class="btn btn-success" @onclick="CreateShipment">Create</button>
                <button class="btn btn-secondary ms-2" @onclick="() => showCreateForm = false">Cancel</button>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Customer</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge bg-@GetStatusColor(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td>
                    <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                    <td>@shipment.CustomerEmail</td>
                    <td>
                        <select class="form-select form-select-sm" value="@shipment.Status"
                                @onchange="(e) => UpdateStatus(shipment.Id, e)">
                            @foreach (var s in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@s">@s</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<Shipment>? shipments;
    private string statusFilter = "";
    private string destinationFilter = "";
    private bool showCreateForm;
    private Shipment newShipment = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private IEnumerable<Shipment> FilteredShipments =>
        shipments!
            .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
            .Where(s => string.IsNullOrEmpty(destinationFilter) ||
                        s.Destination.Contains(destinationFilter, StringComparison.OrdinalIgnoreCase));

    private void ShowCreateForm()
    {
        newShipment = new Shipment();
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        newShipment.TrackingNumber = $"TRK-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(1000, 9999)}";
        newShipment.ShippedDate = DateTime.UtcNow;
        newShipment.EstimatedDelivery = DateTime.UtcNow.AddDays(Random.Shared.Next(3, 14));
        newShipment.Status = ShipmentStatus.Pending;
        await ShipmentService.CreateShipmentAsync(newShipment);
        showCreateForm = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            await LoadShipments();
        }
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="mb-4">
    <div class="input-group" style="max-width: 500px;">
        <input class="form-control" placeholder="Enter tracking number (e.g., TRK-20260612-1234)"
               @bind="trackingNumber" @onkeydown="HandleKeyDown" />
        <button class="btn btn-primary" @onclick="SearchByTracking">Track</button>
    </div>
</div>

@if (searching)
{
    <p><em>Searching...</em></p>
}
else if (searchPerformed && trackedShipment is null)
{
    <div class="alert alert-warning">No shipment found with tracking number "@trackingNumber".</div>
}
else if (trackedShipment is not null)
{
    <div class="card" style="max-width: 600px;">
        <div class="card-header d-flex justify-content-between">
            <strong>@trackedShipment.TrackingNumber</strong>
            <span class="badge bg-@GetStatusColor(trackedShipment.Status)">@trackedShipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">From:</div>
                <div class="col-sm-8">@trackedShipment.Origin</div>
            </div>
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">To:</div>
                <div class="col-sm-8">@trackedShipment.Destination</div>
            </div>
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">Shipped:</div>
                <div class="col-sm-8">@trackedShipment.ShippedDate.ToString("MMMM dd, yyyy")</div>
            </div>
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">Estimated Delivery:</div>
                <div class="col-sm-8">@(trackedShipment.EstimatedDelivery?.ToString("MMMM dd, yyyy") ?? "TBD")</div>
            </div>
            @if (trackedShipment.ActualDelivery.HasValue)
            {
                <div class="row mb-2">
                    <div class="col-sm-4 fw-bold">Delivered:</div>
                    <div class="col-sm-8">@trackedShipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</div>
                </div>
            }
            <div class="row mb-2">
                <div class="col-sm-4 fw-bold">Description:</div>
                <div class="col-sm-8">@trackedShipment.Description</div>
            </div>
        </div>
        <div class="card-footer">
            <ProgressTracker Status="trackedShipment.Status" />
        </div>
    </div>
}

<hr class="my-4" />

<h3>My Shipments</h3>
@if (myShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (myShipments.Count == 0)
{
    <p class="text-muted">No shipments found for your account.</p>
}
else
{
    <div class="row">
        @foreach (var s in myShipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h6 class="card-title">@s.TrackingNumber</h6>
                        <p class="card-text mb-1">
                            <span class="badge bg-@GetStatusColor(s.Status)">@s.Status</span>
                        </p>
                        <p class="card-text mb-1"><small>To: @s.Destination</small></p>
                        <p class="card-text"><small>Est: @(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</small></p>
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-sm btn-outline-primary" @onclick="() => TrackThis(s.TrackingNumber)">Details</button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private string trackingNumber = "";
    private Shipment? trackedShipment;
    private List<Shipment>? myShipments;
    private bool searching;
    private bool searchPerformed;

    [CascadingParameter]
    private Task<AuthenticationState>? AuthState { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (AuthState is not null)
        {
            var state = await AuthState;
            var email = state.User.Identity?.Name ?? "";
            if (!string.IsNullOrEmpty(email))
            {
                myShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
            }
        }
        myShipments ??= [];
    }

    private async Task SearchByTracking()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searching = true;
        searchPerformed = true;
        trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchByTracking();
    }

    private async Task TrackThis(string tracking)
    {
        trackingNumber = tracking;
        await SearchByTracking();
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

@using ShipmentTracker.Client.Models

<div class="d-flex justify-content-between align-items-center">
    @foreach (var step in steps)
    {
        <div class="text-center flex-fill">
            <div class="rounded-circle mx-auto d-flex align-items-center justify-content-center @(IsReached(step) ? "bg-success text-white" : "bg-light text-muted")"
                 style="width: 36px; height: 36px; font-size: 0.8rem;">
                @(IsReached(step) ? "✓" : "○")
            </div>
            <small class="d-block mt-1 @(IsReached(step) ? "fw-bold" : "text-muted")">@step</small>
        </div>
    }
</div>

@code {
    [Parameter]
    public ShipmentStatus Status { get; set; }

    private static readonly ShipmentStatus[] steps =
    [
        ShipmentStatus.Pending,
        ShipmentStatus.PickedUp,
        ShipmentStatus.InTransit,
        ShipmentStatus.OutForDelivery,
        ShipmentStatus.Delivered
    ];

    private bool IsReached(ShipmentStatus step) => Status >= step && Status != ShipmentStatus.Delayed;
}

