@code {
    private string trackingNumber = "";
    private Shipment? trackedShipment;
    private List<Shipment>? myShipments;
    private bool searching;
    private bool searchPerformed;

    [CascadingParameter]
    private Task<AuthenticationState>? AuthState { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (AuthState is not null)
        {
            var state = await AuthState;
            var email = state.User.Identity?.Name ?? "";
            if (!string.IsNullOrEmpty(email))
            {
                myShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
            }
        }
        myShipments ??= [];
    }

    private async Task SearchByTracking()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searching = true;
        searchPerformed = true;
        trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchByTracking();
    }

    private async Task TrackThis(string tracking)
    {
        trackingNumber = tracking;
        await SearchByTracking();
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}
